    "sourceBasis": "Имя прямо названо в аяте.",
    "duaArabic": "يَا حَمِيدُ، أَنْتَ مُسْتَحِقٌّ لِلْحَمْدِ فِي كُلِّ حَالٍ، وَلَوْ غَفَلَ الْخَلْقُ عَنْ ثَنَائِكَ. أَعِنِّي عَلَى ذِكْرِ نِعَمِكَ عِنْدَ الشَّكْوَى، وَاجْعَلْ لِسَانِي يَحْمَدُكَ دُونَ أَنْ يَجْحَدَ فَضْلَكَ عِنْدَ الْبَلَاءِ.",
