    "duaArabic": "يَا قَيُّومُ، تَقُومُ بِنَفْسِكَ وَتُقِيمُ خَلْقَكَ، وَلَا يَسْتَغْنِي عَنْكَ شَيْءٌ. أَصْلِحْ تَدْبِيرَ يَوْمِي، وَأَعِنِّي عَلَى وَاجِبَاتِي عِنْدَ الضَّعْفِ، وَلَا تَجْعَلْنِي أَتَّكِلُ عَلَى نَفْسِي وَأَنْسَى حَاجَتِي إِلَيْكَ.",
