    "dua": "Эй Барподорандаи ҳама чиз! Ту ба зоти Худ қоимӣ ва офаридаҳоятро барпо медорӣ; ҳеҷ чиз аз Ту бениёз нест. Тартиби рӯзамро ислоҳ кун, дар нотавонӣ барои иҷрои вазифаҳоям ёрӣ деҳ ва нагузор ниёзамро ба Ту фаромӯш карда, танҳо ба худ такя кунам.",
    "basis": "Ном дар оят бевосита омадааст; заминаи оят пинак ва хобро нисбат ба Аллоҳ рад мекунад."
