    "dua": "Эй Офаринандаи бисёр! Ҳар чи хоҳӣ, меофарӣ ва фаровонии офаридаҳо Туро ба душворӣ намеандозад. Гумони онро, ки имкониятҳои некӣ тамом шудаанд, аз ман дур кун. Ёрӣ деҳ, ки дар ин рӯзи нав ба кори судманд машғул шавам, на ба нотавонӣ таслим гардам.",
    "basis": "Ном дар оят бевосита омадааст; шакли таъкидии он аз الْخَالِقُ фарқ дорад."
