    "duaArabic": "يَا رَؤُوفُ، رَأْفَتُكَ بِعِبَادِكَ عَظِيمَةٌ، وَأَنْتَ تَعْلَمُ مَا يُثْقِلُ قُلُوبَهُمْ. ارْفُقْ بِي فِي ضَعْفِي، وَأَعِنِّي عَلَى مُوَاسَاةِ الْمَحْزُونِ بِكَلَامٍ لَيِّنٍ، وَلَا تَجْعَلْ نَصِيحَتِي قَسْوَةً تَكْسِرُهُ.",
