    "dua": "Эй Бисёр Дилсӯз! Дилсӯзии Ту ба бандагон бузург аст ва медонӣ, ки дилҳои онҳоро чӣ вазнин мекунад. Дар нотавониам ба ман меҳрубонӣ кун; ёрӣ деҳ, ки андӯҳгинеро бо сухани нарм тасаллӣ диҳам ва нагузор насиҳатам ба сангдилӣ табдил ёфта, ӯро бишканад.",
