    "dua": "Эй Меҳрубон! Бо раҳмати Худ муъминонро ҳидоят мекунӣ ва меомурзӣ; умедворам маро низ бо он фаро бигирӣ. Дар устувории имон ва нигоҳ доштани намоз ёрӣ деҳ; дар рӯзи мулоқот бо Ту, вақте ба омурзишат ниёз дорам, ба ман раҳм кун.",
