    "dua": "Эй Ризқдиҳанда! Ризқи офаридаҳо дар ихтиёри Туст ва неъматҳоят тамом намешаванд. Касби ҳалолро барои таъмини хонаводаам осон гардон ва ёрӣ деҳ, ки дар кор фиреб надиҳам, ҳатто агар аз кам шудани даромад тарсам.",
