    "duaArabic": "يَا شَهِيدُ، أَنْتَ شَاهِدٌ عَلَى مَا جَرَى وَإِنْ أَنْكَرَهُ النَّاسُ، وَلَا يَضِيعُ عِنْدَكَ حَقٌّ. أَعِنِّي عَلَى إِثْبَاتِ حَقِّي بِصِدْقٍ، وَامْنَعْنِي مِنْ شَهَادَةِ الزُّورِ أَوِ الْمُبَالَغَةِ لِأَنْتَصِرَ لِنَفْسِي.",
    "meaning": "Шоҳиди ҳама чиз",
