    "duaArabic": "يَا صَمَدُ، أَنْتَ الْغَنِيُّ عَنْ خَلْقِكَ، وَكُلُّنَا مُحْتَاجُونَ إِلَيْكَ. أَلْجَأُ إِلَيْكَ فِي ضِيقِي، فَاكْفِنِي حَاجَتِي، وَلَا تَجْعَلْنِي أُذِلُّ نَفْسِي لِمَخْلُوقٍ فِي مَعْصِيَتِكَ طَلَبًا لِعَوْنِهِ.",
