    "dua": "Эй Бениёз, ки ҳама ба Ту ниёз доранд! Ту ба офаридаҳо ниёз надорӣ, аммо ҳамаи мо ба Ту ниёз дорем. Дар тангӣ ба Ту паноҳ мебарам: ниёзамро бароварда кун ва нагузор барои ёрии офаридае бо нофармонӣ ба Ту худро назди он хор кунам.",
    "basis": "Ном дар оят бевосита омадааст. Ин шарҳи кӯтоҳ тамоми тафсирҳои номро фаро намегирад."
