    "sourceBasis": "В аяте употреблено عَالِمُ الْغَيْبِ وَالشَّهَادَةِ. Заголовок выделен из этого сочетания согласно перечню.",
    "duaArabic": "يَا عَالِمُ، تَعْلَمُ الْغَيْبَ وَالشَّهَادَةَ، وَلَا أَعْلَمُ مَا يَحْمِلُهُ غَدِي. أَعِنِّي عَلَى تَرْكِ الْكَهَانَةِ وَتَصْدِيقِ الْأَبْرَاجِ، وَعَلَى الِاسْتِعْدَادِ لِلْمُسْتَقْبَلِ بِعَمَلٍ صَالِحٍ وَثِقَةٍ بِعِلْمِكَ.",
