    "duaArabic": "يَا عَزِيزُ، لَا تُغْلَبُ وَلَا يَنْقُصُ مِنْ عِزَّتِكَ تَكَبُّرُ الْمُتَكَبِّرِينَ. أَعِزَّنِي بِطَاعَتِكَ، وَأَعِنِّي عَلَى رَفْضِ رِشْوَةٍ تُذِلُّ دِينِي، وَلَا تَجْعَلْنِي أَطْلُبُ الْعِزَّةَ بِإِهَانَةِ غَيْرِي.",
    "meaning": "Тавоно, Шикастнопазир",
