    "sourceUrl": "https://quran.com/2/255",
    "sourceBasis": "Имя прямо названо в аяте.",
    "duaArabic": "يَا عَظِيمُ، عَظَمَتُكَ لَا تُقَاسُ بِعَظَمَةِ مَخْلُوقٍ، وَكُلُّ كَبِيرٍ صَغِيرٌ أَمَامَ جَلَالِكَ. ارْزُقْنِي خُشُوعًا فِي صَلَاتِي، وَأَعِنِّي عَلَى تَرْكِ مَا يُشْغِلُ قَلْبِي عَنْ تَعْظِيمِكَ حِينَ أَقِفُ بَيْنَ يَدَيْكَ.",
    "meaning": "Бузург, Азим",
