    "duaArabic": "يَا عَفُوُّ، أَرْجُو أَنْ تَمْحُوَ زَلَّاتِي وَتَتَجَاوَزَ عَنْ سُوءِ عَمَلِي. اعْفُ عَنِّي، وَأَعِنِّي عَلَى إِصْلَاحِ مَا أَسَأْتُ، وَعَلَى تَرْكِ التَّشَفِّي بِمَنْ اعْتَذَرَ إِلَيَّ دُونَ إِضَاعَةِ حُقُوقِ الْآخَرِينَ.",
