    "dua": "Эй Маҳвкунандаи гуноҳҳо! Умед дорам, ки лағзишҳоямро маҳв кунӣ ва аз амалҳои бади ман бигзарӣ. Маро бибахш; ёрӣ деҳ бадии расондаамро ислоҳ кунам ва аз қасосгирии бадхоҳона аз касе, ки узр пурсидааст, даст кашам, бе он ки ҳаққи дигаронро нодида гирам.",
    "basis": "Дар оят عَفُوًّا омадааст; дар матни оят гузашт кардани инсонҳо аз бадии расонда низ зикр мешавад."
