    "sourceBasis": "Имя или его грамматическая форма присутствует в указанном аяте; включение следует перечню «Аль-Кава‘ид аль-мусля».",
    "duaArabic": "يَا قَهَّارُ، لَا يَغْلِبُ سُلْطَانَكَ شَيْءٌ، وَالْغَضَبُ الَّذِي يَغْلِبُنِي لَا يَخْرُجُ عَنْ قَهْرِكَ. أَخْضِعْ انْدِفَاعِي لِأَمْرِكَ، وَأَعِنِّي عَلَى أَنْ أَنْسَحِبَ مِنَ الْخِصَامِ قَبْلَ أَنْ أَبْطِشَ بِأَحَدٍ.",
