    "sourceUrl": "https://quran.com/13/9",
    "sourceBasis": "Имя или его грамматическая форма присутствует в указанном аяте; включение следует перечню «Аль-Кава‘ид аль-мусля».",
    "duaArabic": "يَا كَبِيرُ، عَظَمَتُكَ فَوْقَ كُلِّ مَا يُعَظِّمُهُ النَّاسُ، وَلَا يُقَاسُ بِكَ أَحَدٌ. صَغِّرْ فِي قَلْبِي هَمَّ الْمَكَانَةِ وَالثَّنَاءِ، وَأَعِنِّي عَلَى قَوْلِ الْحَقِّ أَمَامَ مَنْ أَهَابُهُ.",
