    "sourceBasis": "Имя или его грамматическая форма присутствует в указанном аяте; включение следует перечню «Аль-Кава‘ид аль-мусля».",
    "duaArabic": "يَا كَرِيمُ، أَكْرَمْتَنِي بِنِعَمٍ لَمْ أَسْتَحِقَّهَا، وَلَمْ تَفْضَحْنِي بِكُلِّ زَلَّةٍ. لَا تَجْعَلْ سِتْرَكَ عَلَيَّ سَبَبًا لِلْغُرُورِ، وَوَفِّقْنِي لِرَدِّ الْأَمَانَةِ وَإِكْرَامِ ضَيْفِي مِنْ غَيْرِ مَنٍّ.",
