    "dua": "Эй Бартар аз ҳама! Ту аз ҳар нуқсон болотарӣ ва ҳеҷ офаридае ба камоли Ту намерасад. Диламро аз монанд кардани Ту ба офаридаҳо пок кун ва ҳадафҳоямро аз корҳои паст ба сӯи итоати Худ боло бардор.",
