    "dua": "Эй Соҳиби бузургии ҳақиқӣ! Бузургӣ танҳо аз они Туст ва маро нашояд бандагони Туро хор шуморам. Худписандиро аз ман дур кун ва ёрӣ деҳ аз касе, ки ӯро хор кардаам, узр пурсам ва ҳақро аз ӯ бипазирам.",
