    "duaArabic": "يَا مَتِينُ، قُوَّتُكَ ثَابِتَةٌ لَا يَلْحَقُهَا وَهَنٌ، وَعَوْنُكَ لَا يَنْقَطِعُ. أَعِنِّي عَلَى رِعَايَةِ وَالِدِيَ الْمَرِيضِ بِصَبْرٍ، وَأَلْهِمْنِي أَنْ أَطْلُبَ الْمُسَاعَدَةَ قَبْلَ أَنْ يَغْلِبَنِيَ التَّعَبُ.",
