    "duaArabic": "يَا مُجِيبُ، تَسْمَعُ نِدَائِي وَتَعْلَمُ مَا يَصْلُحُ لِي قَبْلَ أَنْ أَسْأَلَكَ. أَصْلِحْ مَا بَيْنِي وَبَيْنَ أَخِي، وَاهْدِنِي لِكَلِمَةٍ تَفْتَحُ بَابَ الصُّلْحِ، وَارْزُقْنِيَ الصَّبْرَ فِي انْتِظَارِ الْفَرَجِ.",
