    "duaArabic": "يَا مَجِيدُ، لَكَ الْمَجْدُ وَالْكَمَالُ، وَنِعَمُكَ تَدْعُونِي إِلَى الثَّنَاءِ عَلَيْكَ. اشْغَلْ لِسَانِي بِحَمْدِكَ بَدَلَ الْمُبَاهَاةِ بِنَفْسِي، وَاجْعَلْ عَمَلِي خَالِصًا لَكَ وَلَوْ لَمْ يَعْرِفْهُ أَحَدٌ.",
