    "dua": "Эй Бузургвор! Ҷалолу камол аз они Туст ва неъматҳоят маро ба ситоиши Ту мехонанд. Забонамро ба ҷои худситоӣ ба ситоиши Худ машғул гардон ва амали маро холис барои Худ гардон, ҳатто агар касе аз он огоҳ нашавад.",
