          "id": "umar_accession",
          "titleRu": "Приход к власти в 634 году",
          "textRu": "Перед смертью Абу Бакр предложил Умара своим преемником; после его смерти Умар принял руководство в 634 году. Этот порядок отличался и от обстоятельств Сакифы, и от последующей шуры. Умар получил государство с продолжающимися военными кампаниями и растущими доходами. Ему требовалось согласовывать действия полководцев, назначать представителей в провинциях и решать, как распределять ресурсы между войском, переселенцами и населением новых территорий.",
