          "textRu": "Рассказ о поездке в Сирию показывает управление в условиях неопределённости. В Сарге Умар узнал об эпидемии и последовательно советовался с разными группами спутников. Их мнения расходились. Он решил возвращаться; затем Абд ар-Рахман ибн Ауф сообщил соответствующее наставление Пророка. Решение описано как сочетание обсуждения и учёта переданного знания. Это исторический эпизод ответственности за людей, а не основание обещать, что религиозность делает человека неуязвимым для болезни.",
