      "reignRu": "644–656 гг.",
      "summaryRu": "Ранний мусульманин из Бану Умайя, третий правитель в суннитской последовательности. Его имя связано с переселением в Абиссинию, семейными связями с Пророком, изготовлением согласованных мусхафов, дальнейшим расширением государства и кризисом, завершившимся убийством.",
