          "titleRu": "Шура после Умара",
          "textRu": "После смертельного ранения Умар поручил выбор шести сподвижникам. Среди них были Усман и Али; Абд ар-Рахман ибн Ауф сыграл важную роль в процедуре согласования. Присяга Усману в 644 году стала третьим отличающимся способом передачи власти после Сакифы и рекомендации Абу Бакра. Ход совещаний и условия, о которых спрашивали кандидатов, передаются в различных рассказах. Нельзя говорить, что участвовало всё население растущего государства или что процедура автоматически означала богословское согласие всех будущих мусульманских направлений. Факт начала правления и его религиозное признание различаются.",
          "uncertaintyRu": "Частные речи и формулы принятия условий шуры не воспроизведены как единая бесспорная стенограмма.",
