          "titleRu": "Осада и убийство",
          "textRu": "В 656 году представители недовольных групп из Египта и Ирака оказались в Медине, а дом Усмана был осаждён. Одним из поворотных сюжетов стало обнаруженное письмо с угрозой наказания противникам; его происхождение и ответственность за него в передачах не установлены одинаково. Осада завершилась убийством Усмана в его доме, в 35 году хиджры. Имена непосредственных убийц, роль отдельных участников и возможность предотвращения трагедии передаются неодинаково. Здесь нет категоричного обвинения Аиши, Али или целой общины только на основании их прежней критики.",
