          "titleRu": "Присяга и руководство в Куфе",
          "textRu": "В 656 году после убийства Усмана Али принял присягу. Передачи расходятся о ходе уговоров, сроках и степени свободы отдельных участников. Сирийский наместник Муавия не признал его руководство, связывая требования с наказанием виновных в смерти Усмана. Али должен был одновременно установить управляемость и решать вопрос правосудия; невозможно было считать всю ситуацию уже находившейся под его контролем. После Верблюжьей битвы важнейшим центром стала Куфа. Год 656 означает начало его государственного правления, но в шиитских учениях не дату возникновения самого имамата.",
          "uncertaintyRu": "Требование наказания и вопрос о том, кто фактически обладал полномочиями его осуществить, нельзя отождествлять.",
