      "summaryRu": "Сын Али и Фатимы, внук Пророка. После правления в Куфе заключил соглашение с Муавией. Его государственная роль, имамат и обстоятельства смерти требуют раздельного рассмотрения.",
      "hasanStatusNoteRu": "Хасан ибн Али, внук пророка Мухаммада ﷺ, некоторое время возглавлял мусульманскую общину после смерти своего отца Али. В суннитской традиции его иногда называют пятым праведным халифом. В шиитских традициях его духовный статус и место в истории имамата рассматриваются иначе. Признание его исторического правления и богословская оценка его руководства не полностью совпадают между исламскими направлениями",
