          "text": "Карточкаи 2:127–128 сохтани Хонаро бо дархости қабули амал ва таслим будан ба Аллоҳ мепайвандад. Дар 14:40–41 муроҷиат дар бораи намоз, насл ва омурзиш дар Рӯзи ҳисоб ривоят шудааст. Онҳоро бо назардошти заминаи оятҳо бихонед; ба ин матнҳо шумораи бофташудаи такрор илова нашудааст. Сарчашмаи дуо бо истиноди умумӣ ба тарҷумаи ҳол иваз намешавад."
