      "arabicName": "لُوطٌ",
      "summaryRu": "Лут призывал свой народ отказаться от разврата и ослушания Аллаха. Его история включает угрозу гостям, приход посланцев Аллаха и повеление уйти с семьёй ночью. Аллах спас Лута и его близких, кроме жены, оставшейся среди наказанных. В Коране сохранено его обращение о спасении себя и семьи от происходящего вокруг. Страница различает коранический рассказ и поздние названия городов; точные даты жизни и подтверждённое место погребения не придуманы. Выводы для читателя отделены от самого источника.",
