      "arabicName": "يَعْقُوبُ",
      "summaryRu": "Якуб — пророк, связанный с историей своей семьи и сына Юсуфа. Он услышал сон сына, пережил его исчезновение и долгую разлуку. Коран не скрывает его скорби: от печали ослабело зрение, но он продолжал надеяться на Аллаха и побуждал сыновей искать брата. Позже семья воссоединилась, и зрение вернулось по воле Аллаха. Перед смертью Якуб спрашивал детей о том, кому они будут поклоняться. Точная дата его смерти и полный возраст не указаны.",
