    "translation": {
      "title": "Яъқуб",
      "summary": "Яъқуб паёмбарест, ки қиссааш бо саргузашти оила ва писараш Юсуф пайванд дорад. Ӯ хоби писарашро шунид, нопадид шудани ӯ ва ҷудоии тӯлониро аз сар гузаронд. Қуръон андӯҳи ӯро пинҳон намекунад: аз ғам биноии чашмонаш заиф шуд, вале ӯ ба Аллоҳ умед дошт ва писаронашро ба ҷустуҷӯи бародарашон водор мекард. Баъдтар оила дубора ҷамъ шуд ва бо хости Аллоҳ биноии ӯ барқарор гардид. Пеш аз вафот Яъқуб аз фарзандонаш пурсид, ки киро мепарастанд. Санаи дақиқи вафот ва давомнокии умри ӯ зикр нашудаанд.",
      "sections": [
        {
          "id": "mission",
          "title": "Ҳидоят ва ғамхорӣ ба имони оила",
          "text": "Дар 6:84 Яъқуб аз ҷумлаи касоне ном бурда мешавад, ки Аллоҳ ба онҳо ҳидоят ато кардааст. Сураи «Юсуф» ӯро ҳамчун падаре муаррифӣ мекунад, ки аҳаммияти неъмати паёмбарии писарашро дарк мекунад. Дар 2:133 гуфтугӯи ӯ бо писаронаш ҳангоми наздик шудани марг оварда шудааст: масъалаи асосӣ ибодати Худои ягона аз ҷониби онҳо буд. Ин шаҳодати мушаххаси ғамхорӣ ба имони оила аст; роҳҳои муфассали рисолати худи ӯ дар оятҳои интихобшуда оварда нашудаанд."
        },
        {
          "id": "events",
          "title": "Ҷудоии тӯлонӣ ва умед",
          "text": "Яъқуб хоби Юсуфро шунид ва воқеаҳои ҷудоиро аз сар гузаронд. Дар 12:84 аз андӯҳи сахт ва сафед шудани чашмони ӯ хабар дода мешавад. Дар 12:86 ӯ аз ғаму андӯҳи худ танҳо ба Аллоҳ шикоят мекунад, сипас писаронашро ба ҷустуҷӯи Юсуф ва бародараш ва аз даст надодани умед ба раҳмати Аллоҳ даъват мекунад. Баъдтар ӯ бо Юсуф вомехӯрад; қисса дубора ҷамъ шудани оиларо бо Миср пайванд медиҳад, вале харитаи муосири тамоми роҳро муайян намекунад."
        },
        {
          "id": "gifts",
          "title": "Барқарор шудани биноӣ ва дидор",
          "text": "Дар 12:96 хабар дода мешавад, ки пас аз омадани муждарасон ва гузоштани пироҳан бар рӯйи Яъқуб ӯ дубора бино шуд. Ин воқеаи махсус дар қиссаи паёмбарист, на дастури умумӣ барои табобати бемориҳои чашм бо матоъ ё даст кашидан аз муроҷиат ба духтур. Барқарор шудани биноӣ ва дидор бо наздикон ҳамчун раҳмати Аллоҳ баррасӣ мешаванд. Барнома ба хонанда ваъда намедиҳад, ки бо шумораи муайяни такрори дуо чунин натиҷа ба даст меояд."
        },
        {
          "id": "dates",
          "title": "Аз марг хабар дода шудааст, вале санаи тақвимӣ нест",
          "text": "Ояти 2:133 бевосита аз наздик шудани марги Яъқуб ва гуфтугӯи ӯ бо писаронаш ёд мекунад. Аммо рӯз, соли тақвимӣ, давомнокии умр ва ҷойи дақиқи дафн дар ин оят оварда нашудаанд. Дар ин маҷмӯа онҳо муайян нашудаанд. Худи воқеаи чунин гуфтугӯро наметавон ба хронологияи дақиқ табдил дод; санаҳои тахминии таърихӣ бояд бо сарчашмаи ҷудогонаи мушаххас ҳамроҳ бошанд."
        },
        {
          "id": "duas",
          "title": "Андӯҳе, ки ба Аллоҳ баён шудааст",
          "text": "Дар 12:86 суханони Яъқуб дар бораи танҳо ба Аллоҳ баён кардани ғаму андӯҳи худ нигоҳ дошта шудаанд; дар ин ҷо онҳо ҳамчун қисми қисса шарҳ дода мешаванд, бе он ки бозгӯии таҳрирӣ ба матни ҷудогонаи айнании дуо табдил дода шавад. Дуои худи Юсуф дар саҳифаи ӯ ҷойгир аст ва карточкаи алоҳида дорад. Карточкаи мавҷуднабудаи Яъқуб бо матни аз номи ӯ сохташуда иваз намешавад."
        },
        {
          "id": "lessons",
          "title": "Хулосаҳои таҳрирӣ ва андеша",
          "text": "Сабр маънои набудани ашк ё манъи сухан гуфтан аз дардро надорад. Он метавонад бо умед ва ҷустуҷӯи амалии ёрӣ ҳамроҳ бошад. Савол: чӣ гуна метавонам шахси ғамгинро дастгирӣ кунам, бе он ки аз ӯ фавран бас кардани гиряро талаб намоям? Ин андешаи таҳрирӣ бар асоси қисса аст, на ташхис ё ҳукми ҷудогонаи динӣ дар бораи ҳар навъи эҳсосот."
        }
      ]
    }
