      "titleRu": "Шуайб",
      "arabicName": "شُعَيْبٌ",
      "summaryRu": "Шуайб был послан к мадьянитам и призывал поклоняться Аллаху, честно отмерять и взвешивать, не присваивать чужое и не распространять порчу. Его противники угрожали изгнанием ему и верующим. Он не согласился отказаться от истины и обратился к Аллаху за справедливым решением. Когда пришло повеление, Шуайб и уверовавшие были спасены по милости Всевышнего. Рассказ связан с конкретной нравственной ответственностью в торговле; даты жизни и неподтверждённое отождествление с безымянным старцем из истории Мусы не выданы за факты.",
