      "arabicName": "ذُو الْكِفْلِ",
      "summaryRu": "Зуль-Кифль назван в Коране среди терпеливых, праведных и лучших. Сведения о нём значительно короче, чем рассказы о Мусе или Юсуфе. Эта страница сохраняет именно такой объём знания: имя и нравственная характеристика подтверждены, а народ, места, даты и конкретные испытания не заполнены вымышленной биографией. Его включение в этот раздел не означает, что сами два упоминания прямо называют его пророком. Для этого вопроса требуется отдельное толкование. Краткость сообщения не оправдывает неподтверждённые подробности.",
