      "arabicName": "دَاوُودُ",
      "summaryRu": "Дауд получил от Аллаха власть, мудрость и Забур. Коран сообщает о его победе над Джалутом, о прославляющих вместе с ним горах и птицах, о мягкости железа и изготовлении кольчуг. Его положение было связано не только с силой, но и с обязанностью справедливого суда. Рассказ об обращении спорящих сторон напоминает об испытании властью. Точные календарные даты его рождения и смерти в выбранных источниках не установлены; популярные добавления к истории не выдаются за Коран.",
