    "translation": {
      "title": "Довуд",
      "summary": "Довуд аз Аллоҳ ҳокимият, ҳикмат ва Забурро гирифт. Қуръон аз пирӯзии ӯ бар Ҷолут, кӯҳҳо ва парандаҳое, ки ҳамроҳи ӯ Аллоҳро тасбеҳ мегуфтанд, нарм шудани оҳан ва сохтани зиреҳҳо хабар медиҳад. Мақоми ӯ на танҳо бо қудрат, балки бо вазифаи доварии одилона алоқаманд буд. Қиссаи муроҷиати тарафҳои баҳскунанда озмоиш бо ҳокимиятро ёдрас мекунад. Санаҳои дақиқи тақвимии таваллуду вафоти ӯ дар сарчашмаҳои интихобшуда муайян нашудаанд; иловаҳои маъруф ба қисса ҳамчун матни Қуръон пешниҳод намешаванд.",
      "sections": [
        {
          "id": "mission",
          "title": "Ҳокимият, ҳикмат ва Китоб",
          "text": "Пас аз қиссаи рӯбарӯшавӣ бо лашкари Ҷолут Қуръон хабар медиҳад, ки Довуд Ҷолутро кушт ва аз Аллоҳ ҳокимият ва ҳикмат гирифт. Дар 4:163 Забур, ки ба ӯ ато шуда буд, ҷудогона ном бурда мешавад. Инҳо маълумоти асосӣ дар бораи мақоми Довуданд; худ аз худ хронологияи дақиқи ҳукмронӣ ё рӯйхати марзҳои онро намедиҳанд. Оғози ин қисса, 2:246, онро бевосита бо Банӣ Исроил пас аз Мусо мепайвандад."
        },
        {
          "id": "events",
          "title": "Озмоиш дар доварӣ",
          "text": "Сураи «Сод» дар бораи баҳскунандагоне қисса мекунад, ки ногаҳон назди Довуд даромаданд, инчунин аз қарори ӯ, дарк кардани озмоиш ва омурзиш хостанаш аз Аллоҳ хабар медиҳад. Сипас амр меояд, ки одилона доварӣ кунад ва аз ҳавои нафс пайравӣ накунад. Карточка ба ин қиссаи зино ё куштореро илова намекунад, ки ин оятҳо баён накардаанд."
        },
        {
          "id": "gifts",
          "title": "Неъматҳои махсуси Аллоҳ",
          "text": "Ба кӯҳҳо ва парандаҳо амр шуда буд, ки ҳамроҳи Довуд Аллоҳро тасбеҳ гӯянд; оҳан барои ӯ нарм карда шуд. Ба ӯ амр гардид, ки зиреҳҳои комил бисозад ва андозаро дар бофтани онҳо риоя кунад. Ин қисса дар бораи неъмат ва масъулият барои кори муфид аст, на дастури ба даст овардани қудрати фавқуттабиӣ бар филиз."
        },
        {
          "id": "dates",
          "title": "Таваллуд, вафот ва замони зиндагӣ",
          "text": "Дар матнҳои қуръонии овардашуда санаи тақвимии таваллуд ё вафот ва давомнокии умри Довуд нест. Санаҳои дақиқи боэътимод барои ин нусха муайян нашудаанд. Пайванди ӯ бо Сулаймон дар 27:16 тасдиқ мешавад; аз рӯйи ин робита муайян кардани асри мушаххас ё бе қайду шарт пазируфтани маълумоти сайёҳӣ дар бораи қабр пешниҳод намешавад."
        },
        {
          "id": "dua",
          "title": "Дуо дар қиссаи вобаста",
          "text": "Пайванд ба 2:250 ба дуои мӯъминон пеш аз ҷанг бо Ҷолут мебарад. Муҳим: ин муроҷиати гурӯҳе дар қиссаи Толут аст, на матни ҷудогонаи дуое, ки Қуръон онро айнан ба Довуд нисбат дода бошад. Ин ҳудуди муаллифият нигоҳ дошта мешавад; дуои шахсии санҷиданашудаи Довуд илова нашудааст."
        },
        {
          "id": "lessons",
          "title": "Шарҳи таҳрирӣ ва савол",
          "text": "Мақоми роҳбар қобилияти гӯш кардан, санҷидани баҳс ва бозгашт ба адолатро талаб мекунад. Савол: оё майли ман ба яке аз тарафҳо ба қароре, ки барои он масъулам, таъсир мерасонад ва оё барои ислоҳи хато омодаам?"
        }
      ]
    }
