          "id": "dates",
          "titleRu": "Рождение, смерть, время и дуа",
          "kind": "editorial",
          "textRu": "Надёжные точные даты рождения и смерти, возраст и место погребения для этого набора не установлены. Из указанного отрывка нельзя вывести утверждение о продолжающейся земной жизни Ильяса. Самостоятельное переданное дуа Ильяса здесь также не установлено и не заменено составленной формулой.",
