    "translation": {
      "title": "Илёс",
      "summary": "Илёс дар Қуръон бевосита яке аз фиристодагон номида шудааст. Ӯ қавмашро ба тақво даъват мекард ва рӯ овардан ба Баълро ба ҷойи ибодати Аллоҳ маҳкум менамуд. Мардум ӯро дурӯғгӯ шумориданд, аммо Қуръон ёди неки ӯро нигоҳ медорад ва бандагони имондорро ёд мекунад. Қисса кӯтоҳ аст: он номи шаҳр, қавми мушаххас ба маънои қавмшиносӣ, таваллуду вафот ё муъҷизаи ҷудогонаро муайян намекунад. Аз ин рӯ саҳифа даъвати тасдиқшударо аз як донистани ӯ бо шахсиятҳои тарҷумаи ҳолҳои баъдӣ ҷудо мекунад ва ҷойҳои холиро бо афсона пур намекунад. Барои андеша саволе дар бораи асосҳои ибодати одатшуда пешниҳод шудааст.",
      "sections": [
        {
          "id": "mission",
          "title": "Фиристода ва даъвати ӯ",
          "text": "Дар 37:123 Илёс яке аз фиристодагон номида мешавад. Ӯ қавмашро ба тақво ёдовар шуда, онҳоро барои рӯ овардан ба Баъл ва тарк кардани ибодати Аллоҳ, Парвардигори худ ва наслҳои пешинаашон, сарзаниш мекард. Қуръон мазмуни даъватро хабар медиҳад; номи шаҳр ва ҷойгиршавии ҷуғрофии муосир дар ин порча оварда нашудаанд."
        },
        {
          "id": "events",
          "title": "Рад шудани даъват ва боқӣ мондани ёди нек",
          "text": "Дар идома гуфта мешавад, ки ӯро дурӯғгӯ шумориданд, ва барои бандагони мухлиси Аллоҳ истисно оварда мешавад. Қисса бо ёди нек, салом ва ишора ба имон анҷом меёбад. Аз пайдарҳамии кӯтоҳи ин оятҳо наметавон ҳамаи сафарҳои Илёс, шумораи пайравонаш ё тақвими муфассали муқобилиятро барқарор кард."
        },
        {
          "id": "gifts",
          "title": "Дар бораи неъматҳои махсус чӣ маълум аст",
          "text": "Фиристода будани ӯ ва ситоиши Аллоҳ тасдиқ шудаанд. Муъҷизаи ҷудогона, масалан қиссаи мушаххаси оташи осмонӣ ё хушксолии махсус, дар оятҳои интихобшуда баён нашудааст; аз ин рӯ дар ин ҷо ҳамчун хабари қуръонӣ пешниҳод намешавад. Он чи зикр нашудааст, инкор намегардад, вале пеш аз илова кардан асоси ҷудогонаи боэътимод талаб мекунад."
        },
        {
          "id": "dates",
          "title": "Таваллуд, вафот, замон ва дуо",
          "text": "Санаҳои дақиқу боэътимоди таваллуду вафот, синну сол ва ҷойи дафн барои ин маҷмӯа муайян нашудаанд. Аз порчаи зикршуда наметавон хулоса кард, ки зиндагии заминии Илёс то ҳол идома дорад. Дуои мустақили ривоятшудаи Илёс низ дар ин ҷо муайян нашудааст ва бо матни сохташуда иваз намегардад."
        },
        {
          "id": "lessons",
          "title": "Шарҳи таҳрирӣ ва савол",
          "text": "Одатӣ будани номи гиромидошташаванда ё маросим худ аз худ ҳақ будани ибодатро исбот намекунад. Савол: оё метавонам асоси амалҳои динии одатшударо бисанҷам ва ҳамзамон эҳтироми мардум ва вафодорӣ ба тавҳидро нигоҳ дорам?"
        }
      ]
    }
